def parse_requirements(text):
    result = {}
    for line in text.split('\n'):
        if line.strip():
            name, version = line.split('==')
            result[name] = version
    return result

def requirement_names(text):
    names = []
    for line in text.split('\n'):
        if line.strip():
            names.append(line.split('==')[0])
    return names

