class Shell:
    def __init__(self):
        self.active = False
        self.global_packages = []
        self.venv_packages = []
    def pip_install(self, name):
        if self.active:
            self.venv_packages.append(name)
        else:
            self.global_packages.append(name)

sh = Shell()
sh.pip_install('numpy')
sh.active = True
sh.pip_install('Flask')
print(sh.global_packages, sh.venv_packages)

